export const defaults={strategy:'ma',fast:10,slow:30,rsiPeriod:14,rsiBuy:30,rsiSell:70,bbPeriod:20,bbMult:2,capital:100000,allocation:95,commission:0.03,minCommission:5,stamp:0.05,transfer:0.001,slippage:5,limit:10,stop:8,take:20,from:'2023-01-03',to:'2025-12-31'};
export function demoData(){let seed=9271,p=24,last=p;const out=[];const rand=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;};for(let d=new Date('2022-07-01T00:00:00Z'),i=0;d<=new Date('2025-12-31T00:00:00Z');d.setUTCDate(d.getUTCDate()+1)){if([0,6].includes(d.getUTCDay()))continue;const open=p*(1+(rand()-.5)*.014);p=Math.max(5,open*(1+Math.sin(i/39)*.0035+(rand()-.49)*.037));out.push({date:d.toISOString().slice(0,10),open:+open.toFixed(2),high:+(Math.max(open,p)*(1+rand()*.018)).toFixed(2),low:+(Math.min(open,p)*(1-rand()*.018)).toFixed(2),close:+p.toFixed(2),volume:Math.floor(700000+rand()*4500000),prev_close:+last.toFixed(2)});last=p;i++;}return out;}
export function parseCSV(text){
  const lines=text.replace(/^\uFEFF/,'').trim().split(/\r?\n/);if(lines.length<3)throw Error('CSV 至少需要两行日线数据。');if(lines.length>12001)throw Error('最多支持 12,000 行日线数据。');
  const split=s=>{let a=[],v='',q=false;for(let i=0;i<s.length;i++){let c=s[i];if(c==='"'){if(q&&s[i+1]==='"'){v+='"';i++;}else q=!q;}else if(c===','&&!q){a.push(v.trim());v='';}else v+=c;}if(q)throw Error('CSV 引号未闭合。');a.push(v.trim());return a;};
  const aliases={'日期':'date','开盘':'open','最高':'high','最低':'low','收盘':'close','成交量':'volume','昨收':'prev_close','复权收盘':'signal_close','涨停价':'limit_up','跌停价':'limit_down'};
  const headers=split(lines[0]).map(s=>aliases[s]||s.toLowerCase());const required=['date','open','high','low','close','volume'];for(const k of required)if(!headers.includes(k))throw Error('缺少列：'+k);if(new Set(headers).size!==headers.length)throw Error('CSV 存在重复列名。');
  const seen=new Set();const data=lines.slice(1).filter(s=>s.trim()).map((s,i)=>{const vals=split(s);if(vals.length!==headers.length)throw Error('第 '+(i+2)+' 行列数不一致。');const r={};headers.forEach((h,j)=>{if(vals[j]!=='')r[h]=h==='date'?vals[j]:Number(vals[j]);});if(!/^\d{4}-\d{2}-\d{2}$/.test(r.date)||!Number.isFinite(Date.parse(r.date))||new Date(r.date).toISOString().slice(0,10)!==r.date)throw Error('第 '+(i+2)+' 行日期格式应为 YYYY-MM-DD。');if(seen.has(r.date))throw Error('存在重复日期：'+r.date);seen.add(r.date);for(const k of required.slice(1))if(!Number.isFinite(r[k])||r[k]<(k==='volume'?0:0.000001))throw Error('第 '+(i+2)+' 行 '+k+' 无效。');if(r.high<Math.max(r.open,r.close)||r.low>Math.min(r.open,r.close)||r.low>r.high)throw Error('第 '+(i+2)+' 行 OHLC 价格关系不正确。');for(const k of ['prev_close','signal_close','limit_up','limit_down'])if(r[k]!==undefined&&(!Number.isFinite(r[k])||r[k]<=0))throw Error('第 '+(i+2)+' 行 '+k+' 无效。');if((r.limit_up===undefined)!==(r.limit_down===undefined))throw Error('涨停价与跌停价需成对提供。');if(r.limit_up!==undefined&&r.limit_up<r.limit_down)throw Error('涨停价不能低于跌停价。');return r;});data.sort((a,b)=>a.date.localeCompare(b.date));if(data.some(r=>r.signal_close!==undefined)&&data.some(r=>r.signal_close===undefined))throw Error('signal_close 列必须每行都有数值。');return data;
}
export function sma(xs,n){let sum=0;return xs.map((v,i)=>{sum+=v;if(i>=n)sum-=xs[i-n];return i>=n-1?sum/n:null;});}
export function ema(xs,n){let prev=xs[0];return xs.map((v,i)=>prev=i? v*2/(n+1)+prev*(1-2/(n+1)):v);}
export function indicators(data,c){const xs=data.map(x=>x.signal_close??x.close),fast=sma(xs,c.fast),slow=sma(xs,c.slow),e12=ema(xs,12),e26=ema(xs,26),dif=e12.map((v,i)=>v-e26[i]),dea=ema(dif,9);let gain=0,loss=0;const rsi=xs.map((v,i)=>{if(!i)return null;const d=v-xs[i-1];if(i<=c.rsiPeriod){gain+=Math.max(d,0)/c.rsiPeriod;loss+=Math.max(-d,0)/c.rsiPeriod;}else{gain=(gain*(c.rsiPeriod-1)+Math.max(d,0))/c.rsiPeriod;loss=(loss*(c.rsiPeriod-1)+Math.max(-d,0))/c.rsiPeriod;}return i<c.rsiPeriod?null:loss===0?(gain===0?50:100):100-100/(1+gain/loss);});const mid=sma(xs,c.bbPeriod),std=xs.map((v,i)=>mid[i]===null?null:Math.sqrt(xs.slice(i-c.bbPeriod+1,i+1).reduce((s,x)=>s+(x-mid[i])**2,0)/c.bbPeriod));return {xs,fast,slow,dif,dea,rsi,mid,std};}
export function validate(c){for(const [k,v]of Object.entries(c))if(typeof defaults[k]==='number'&&!Number.isFinite(v))throw Error('参数必须是有效数字。');if(!['ma','macd','rsi','boll'].includes(c.strategy))throw Error('策略无效。');for(const k of ['fast','slow','rsiPeriod','bbPeriod'])if(!Number.isInteger(c[k])||c[k]<2||c[k]>250)throw Error('指标周期需为 2–250 的整数。');if(c.fast>=c.slow)throw Error('短期均线必须小于长期均线。');if(c.capital<1000||c.capital>1e9)throw Error('初始资金需在 1,000–10 亿之间。');if(c.allocation<=0||c.allocation>100)throw Error('仓位需在 0–100% 之间。');if(c.rsiBuy<0||c.rsiSell>100||c.rsiBuy>=c.rsiSell)throw Error('RSI 买入阈值必须低于卖出阈值，范围为 0–100。');if(c.bbMult<=0||c.bbMult>5)throw Error('布林带倍数需在 0–5 之间。');for(const k of ['commission','stamp','transfer','slippage','stop','take','minCommission'])if(c[k]<0)throw Error('成本与风控参数不能为负数。');if(c.stop>100||c.take>1000||c.slippage>1000||c.commission>5||c.stamp>5||c.transfer>5||c.minCommission>10000)throw Error('成本或风控参数超出合理范围。');if(![0,5,10,20,30].includes(c.limit))throw Error('涨跌停比例无效。');if(!/^\d{4}-\d{2}-\d{2}$/.test(c.from)||!/^\d{4}-\d{2}-\d{2}$/.test(c.to)||c.from>=c.to)throw Error('开始日期必须早于结束日期。');}
export function backtest(data,config){const c={...defaults,...config};validate(c);const ind=indicators(data,c);const warm={ma:c.slow,macd:35,rsi:c.rsiPeriod+1,boll:c.bbPeriod}[c.strategy];const start=data.findIndex(r=>r.date>=c.from);const end=data.findLastIndex(r=>r.date<=c.to);if(start<0||end<=start)throw Error('所选日期内至少需要两个交易日。');if(start<warm)throw Error('开始日期前至少需要 '+warm+' 条日线作为指标预热，请延后开始日期或补充数据。');let cash=c.capital,qty=0,entry=null,fees=0,peak=c.capital,desired=false,blocked=0;const trades=[],closed=[],curve=[];const fee=(amount,sell)=>Math.max(c.minCommission,amount*c.commission/100)+amount*c.transfer/100+(sell?amount*c.stamp/100:0);const signal=(i,held)=>{if(c.strategy==='ma')return ind.fast[i]>ind.slow[i];if(c.strategy==='macd')return ind.dif[i]>ind.dea[i];if(c.strategy==='rsi')return ind.rsi[i]<c.rsiBuy?true:ind.rsi[i]>c.rsiSell?false:held;const lower=ind.mid[i]-c.bbMult*ind.std[i];return ind.xs[i]<lower?true:ind.xs[i]>=ind.mid[i]?false:held;};
  for(let i=start;i<=end;i++){const r=data[i],prev=data[i-1];desired=signal(i-1,desired);let reason='指标信号';if(qty&&entry){const change=prev.close/entry.price-1;if(c.stop>0&&change<=-c.stop/100){desired=false;reason='收盘止损';}if(c.take>0&&change>=c.take/100){desired=false;reason='收盘止盈';}}
    const prevPrice=r.prev_close??prev.close;const up=r.limit_up??(c.limit?Math.round(prevPrice*(1+c.limit/100)*100)/100:Infinity);const down=r.limit_down??(c.limit?Math.round(prevPrice*(1-c.limit/100)*100)/100:0);const sell=qty>0&&!desired,buy=qty===0&&desired;const tradeable=r.volume>0&&(sell?r.open>down+0.001:r.open<up-0.001);
    if((buy||sell)&&!tradeable)blocked++;
    if(sell&&tradeable&&r.date>entry.date){const price=Math.max(r.low,down,r.open*(1-c.slippage/10000));const amount=qty*price,f=fee(amount,true),pnl=amount-f-entry.cost;cash+=amount-f;fees+=f;trades.push({date:r.date,side:'卖出',price,quantity:qty,amount,fee:f,reason,pnl});closed.push({entry:entry.date,exit:r.date,pnl,return:pnl/entry.cost,days:i-entry.index});qty=0;entry=null;}
    if(buy&&tradeable){const price=Math.min(r.high,up,r.open*(1+c.slippage/10000));let n=Math.floor((cash*c.allocation/100)/(price*100))*100;while(n>0&&n*price+fee(n*price,false)>cash)n-=100;if(n>0){const amount=n*price,f=fee(amount,false);qty=n;cash-=amount+f;fees+=f;entry={date:r.date,price,cost:amount+f,index:i};trades.push({date:r.date,side:'买入',price,quantity:n,amount,fee:f,reason:'指标信号',pnl:null});}}
    const equity=cash+qty*r.close;peak=Math.max(peak,equity);curve.push({date:r.date,equity,nav:equity/c.capital,benchmark:r.close/data[start].open,drawdown:equity/peak-1,cash,quantity:qty});
  }
  const last=curve.at(-1),total=last.nav-1,annual=last.nav**(252/curve.length)-1;const rs=curve.map((r,i)=>r.equity/(i?curve[i-1].equity:c.capital)-1);const mean=rs.reduce((s,x)=>s+x,0)/rs.length,sd=Math.sqrt(rs.reduce((s,x)=>s+(x-mean)**2,0)/Math.max(1,rs.length-1));const maxdd=Math.min(0,...curve.map(r=>r.drawdown));const wins=closed.filter(t=>t.pnl>0),losses=closed.filter(t=>t.pnl<0);return {config:c,curve,trades,closed,metrics:{total,annual,maxdd,sharpe:sd>0?mean/sd*Math.sqrt(252):null,winrate:closed.length?wins.length/closed.length:null,profitFactor:losses.length?wins.reduce((s,x)=>s+x.pnl,0)/-losses.reduce((s,x)=>s+x.pnl,0):null,fees,blocked,equity:last.equity,quantity:qty,cash,benchmark:last.benchmark-1,excess:total-(last.benchmark-1),volatility:sd*Math.sqrt(252)},period:{from:curve[0].date,to:last.date,bars:curve.length}};
}
